-- ============================================
-- 1. Partial Unique Index for High-Concurrency Booking
-- ============================================

-- This index ensures atomic slot allocation by preventing double-booking
-- It only applies to active bookings (PENDING, CONFIRMED, COMPLETED)
CREATE UNIQUE INDEX IF NOT EXISTS appointment_slot_occupied 
ON bookings(time_slot_id, appointment_date, slot_sequence)
WHERE status IN ('PENDING', 'CONFIRMED', 'COMPLETED');

COMMENT ON INDEX appointment_slot_occupied IS 'Ensures atomic booking by preventing double-booking of the same time slot sequence';

-- ============================================
-- 2. Function and Trigger for Automatic Sequence Increment
-- ============================================

-- Function to increment current_sequence in time_slots when a booking is created
CREATE OR REPLACE FUNCTION increment_time_slot_sequence()
RETURNS TRIGGER AS $$
BEGIN
  -- Only increment for PENDING or CONFIRMED bookings
  IF NEW.status IN ('PENDING', 'CONFIRMED') THEN
    UPDATE time_slots 
    SET current_sequence = current_sequence + 1
    WHERE id = NEW.time_slot_id;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to automatically increment sequence on booking creation
DROP TRIGGER IF EXISTS booking_created_trigger ON bookings;
CREATE TRIGGER booking_created_trigger
AFTER INSERT ON bookings
FOR EACH ROW
EXECUTE FUNCTION increment_time_slot_sequence();

-- ============================================
-- 3. Additional Performance Indexes
-- ============================================

-- Index for fast time slot queries by service and date range
CREATE INDEX IF NOT EXISTS idx_time_slots_service_date 
ON time_slots(service_id, start_time, end_time);

-- Index for user booking history
CREATE INDEX IF NOT EXISTS idx_bookings_user_date 
ON bookings(user_id, appointment_date DESC);

-- Index for time slot availability queries
CREATE INDEX IF NOT EXISTS idx_bookings_slot_status 
ON bookings(time_slot_id, appointment_date, status);

-- Index for service filtering
CREATE INDEX IF NOT EXISTS idx_services_active 
ON services(active, created_at DESC);

-- Index for user lookup
CREATE INDEX IF NOT EXISTS idx_users_email 
ON users(email);

-- ============================================
-- 4. View for Available Time Slots
-- ============================================

-- Materialized view for available time slots (can be refreshed periodically)
-- Or regular view for real-time queries (slower but up-to-date)
CREATE OR REPLACE VIEW available_time_slots AS
SELECT 
  ts.id,
  ts.service_id,
  s.name as service_name,
  ts.start_time,
  ts.end_time,
  ts.capacity,
  COALESCE(b.booked_count, 0) as booked_count,
  ts.capacity - COALESCE(b.booked_count, 0) as available_slots,
  ts.current_sequence,
  ts.created_at
FROM time_slots ts
JOIN services s ON ts.service_id = s.id
LEFT JOIN (
  SELECT 
    time_slot_id,
    appointment_date::date as slot_date,
    COUNT(*) as booked_count
  FROM bookings
  WHERE status IN ('PENDING', 'CONFIRMED')
  GROUP BY time_slot_id, appointment_date::date
) b ON ts.id = b.time_slot_id 
  AND ts.start_time::date = b.slot_date
WHERE s.active = true
  AND ts.start_time > NOW()
ORDER BY ts.start_time;

COMMENT ON VIEW available_time_slots IS 'Real-time view of available time slots with capacity information';

