-- ============================================
-- 7. Seed Data Insertion Functions
-- ============================================

-- Function to generate sample time slots (for testing)
CREATE OR REPLACE FUNCTION generate_sample_time_slots(
  p_service_id UUID,
  p_start_date DATE,
  p_days INTEGER
)
RETURNS INTEGER AS $$
DECLARE
  v_counter INTEGER := 0;
  v_current_date DATE;
  v_start_time TIMESTAMP;
  v_end_time TIMESTAMP;
BEGIN
  FOR i IN 0..(p_days - 1) LOOP
    v_current_date := p_start_date + i;
    
    -- Generate time slots from 9 AM to 5 PM, every 30 minutes
    FOR hour IN 9..16 LOOP
      FOR minute IN 0..1 LOOP
        v_start_time := v_current_date + (hour * INTERVAL '1 hour') + (minute * 30 * INTERVAL '1 minute');
        v_end_time := v_start_time + INTERVAL '30 minutes';
        
        INSERT INTO time_slots (
          id, service_id, start_time, end_time, 
          capacity, current_sequence, created_at, updated_at
        ) VALUES (
          uuid_generate_v4(),
          p_service_id,
          v_start_time,
          v_end_time,
          1 + floor(random() * 3), -- Random capacity 1-3
          0,
          NOW(),
          NOW()
        );
        
        v_counter := v_counter + 1;
      END LOOP;
    END LOOP;
  END LOOP;
  
  RETURN v_counter;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION generate_sample_time_slots IS 'Helper function to generate sample time slots for testing';

